async function insertPhoto(photo) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify([photo]);
    const options = {
      hostname: SUPABASE_URL,
      path: '/rest/v1/stop_photos',
      method: 'POST',
      headers: {
        'apikey': SERVICE_KEY,
        'Authorization': `Bearer ${SERVICE_KEY}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal',
        'Content-Length': Buffer.byteLength(data)
      }
    };
    const req = https.request(options, (res) => {
      res.on('data', () => {});
      res.on('end', () => resolve(res.statusCode));
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

async function main() {
  let success = 0, failed = 0;
  for (let i = 0; i < photos.length; i++) {
    try {
      const status = await insertPhoto(photos[i]);
      if (status === 201 || status === 200) {
        success++;
        if (success % 10 === 0) console.log(`Inserted ${success}/${photos.length} photos...`);
      } else {
        failed++;
        console.log(`Failed photo ${i}: status ${status}`);
      }
    } catch(e) {
      failed++;
      console.log(`Error photo ${i}:`, e.message);
    }
  }
  console.log(`\nDone! Success: ${success}, Failed: ${failed}`);
}

main();
